"""Build an eight-chapter Physics revision wing in the existing Focus site."""
from pathlib import Path
import html, json, subprocess

R=Path(__file__).resolve().parent / 'asseb-half-yearly-study-plan-2026' if Path(__file__).resolve().parent.name != 'asseb-half-yearly-study-plan-2026' else Path(__file__).resolve().parent
E=lambda s:html.escape(str(s),quote=True)
book='https://share.google/ysPTqIcLy1KxMdyS7'
chapters=[
 dict(id='electric-charges-fields',title='Electric Charges & Fields',pages='5–54',scope='Charge, Coulomb’s law, electric field, dipole, flux and Gauss’s law.',
 concept='Charge is conserved and quantised. The electric field is force per unit positive test charge. Flux counts the field passing through a surface; Gauss’s law relates closed-surface flux to enclosed charge.',
 formulas=[('Coulomb’s law','F = k|q₁q₂|/r²; k = 1/(4πε₀)','Force along the line joining point charges.'),('Electric field','E = F/q₀; E = k|q|/r²','Field of a point charge; direction matters.'),('Flux and Gauss','Φ = ∫E·dA; ∮E·dA = Q_enclosed/ε₀','For a uniform field on a plane: Φ = EA cosθ; θ is to the surface normal.'),('Dipole','p = q(2a); τ = pE sinθ','p points from negative to positive charge.'),('Symmetry results','E_line = λ/(2πε₀r); E_sheet = σ/(2ε₀)','Infinite line and infinite non-conducting sheet.')],
 derivation=('Field of an infinite line via Gauss’s law','Choose a closed coaxial cylinder of radius r and length L. By symmetry E is radial and constant on the curved side; flux through its flat ends is zero. Therefore ∮E·dA = E(2πrL) = λL/ε₀, so E = λ/(2πε₀r). State why this method requires an effectively infinite, uniform line.'),
 example=('Two equal charges','Two +2 μC point charges are 0.30 m apart. Find the force magnitude.','F = (9 × 10⁹)(2 × 10⁻⁶)²/(0.30)² = 0.40 N. It is repulsive.'),
 questions=[('What does a closed Gaussian surface with no enclosed net charge tell you?','Its net flux is zero, but the electric field at points on it need not be zero.'),('Why do field lines never cross?','A crossing would give two field directions at one point, which is impossible.')]),
 dict(id='potential-capacitance',title='Potential & Capacitance',pages='55–96',scope='Potential, equipotentials, dipole energy, capacitors, dielectrics and stored energy.',
 concept='Potential is electric potential energy per unit charge. Electric field points towards decreasing potential. Capacitance measures charge stored per volt; the dielectric changes capacitance and may change charge or voltage depending on what is held fixed.',
 formulas=[('Potential','V = kq/r; ΔU = qΔV','Potential is a scalar; take care with charge signs.'),('Field–potential','E = −dV/dr (along r)','Use the negative gradient in the field direction.'),('Capacitance','C = Q/V; C_parallel plate = ε₀A/d','With fully filled dielectric: C = κ ε₀A/d.'),('Networks','C_parallel = ΣCᵢ; 1/C_series = Σ1/Cᵢ','Parallel: same V. Series: same charge magnitude.'),('Energy','U = ½CV² = Q²/(2C) = ½QV','Use the correct constraints after disconnecting a battery.')],
 derivation=('Parallel-plate capacitor','Take two large plates ±Q, area A, separation d. Ignoring edge effects, each sheet contributes σ/(2ε₀), so between plates E = σ/ε₀ = Q/(ε₀A). Potential difference V = Ed = Qd/(ε₀A). Hence C = Q/V = ε₀A/d. With a full dielectric, replace ε₀ by κ ε₀.'),
 example=('Series capacitors','A 2 μF and a 3 μF capacitor are in series across 10 V. Find Q and the voltage across 2 μF.','C_eq = (2×3)/(2+3) = 1.2 μF; Q = C_eqV = 12 μC. V₂ = Q/C₂ = 6 V (and V₃ = 4 V).'),
 questions=[('Can an equipotential surface cross an electric field line at an oblique angle?','No. The field is perpendicular to an equipotential surface.'),('What stays constant for a capacitor disconnected from its battery?','Charge Q (assuming no leakage); voltage can change.')]),
 dict(id='current-electricity',title='Current Electricity',pages='97–135',scope='Drift, Ohm’s law, resistivity, cells, Kirchhoff rules and Wheatstone bridge.',
 concept='Electric current is a rate of charge flow. Resistivity is a material property; resistance also depends on length and cross-section. Kirchhoff’s rules conserve charge at a junction and energy around a loop.',
 formulas=[('Current and drift','I = neAv_d; J = I/A','n: carrier density, e: charge magnitude, A: cross-section.'),('Resistance','V = IR; R = ρL/A','For a metal near a reference temperature: R ≈ R₀[1 + αΔT].'),('Power','P = VI = I²R = V²/R','Distinguish heat in a resistor from total battery power.'),('Cell with internal resistance','V_terminal = ε − Ir (discharging)','I = ε/(R+r) for one external resistance R.'),('Wheatstone balance','P/Q = R/S','At balance the galvanometer current is zero.')],
 derivation=('Microscopic Ohm’s law','An electron with mean time τ between collisions gains mean drift speed magnitude v_d = eEτ/m. Current I = neAv_d = ne²AτE/m. Since E = V/L, I = (ne²τA/mL)V. Therefore R = mL/(ne²τA), so ρ = m/(ne²τ). State the simple Drude-model assumptions.'),
 example=('Cell and load','A 12 V cell with internal resistance 1 Ω is connected to a 5 Ω resistor. Find I and terminal voltage.','I = 12/(5+1) = 2 A. Terminal voltage = 12 − 2(1) = 10 V; also IR = 10 V.'),
 questions=[('Why does a balanced Wheatstone bridge have no galvanometer current?','Its two junctions are at equal potential.'),('When is terminal voltage less than emf?','When a cell is delivering current through its internal resistance.')]),
 dict(id='moving-charges-magnetism',title='Moving Charges & Magnetism',pages='136–176',scope='Lorentz force, circular motion, Biot–Savart, Ampère, parallel wires and galvanometer.',
 concept='A moving charge experiences a magnetic force perpendicular to both velocity and field. A steady current creates a magnetic field; symmetry makes Ampère’s law useful for long straight conductors and solenoids.',
 formulas=[('Force on a charge','F = q(v × B); |F| = |q|vB sinθ','Magnetic force does no work on a charge.'),('Circular motion','r = mv/(|q|B); T = 2πm/(|q|B)','For v perpendicular to uniform B.'),('Straight wire and loop','B_wire = μ₀I/(2πr); B_loop centre = μ₀NI/(2R)','Ideal geometries; N turns in the loop.'),('Ampère and solenoid','∮B·dl = μ₀I_enclosed; B_solenoid ≈ μ₀nI','n is turns per unit length; ideal long solenoid.'),('Current loop','m = NIA; τ = mB sinθ','m is magnetic dipole moment.')],
 derivation=('Field around a long straight wire','Take an Amperian circle of radius r centred on the long wire. Cylindrical symmetry makes B tangential and equal in magnitude everywhere on it. ∮B·dl = B(2πr) = μ₀I, giving B = μ₀I/(2πr). Use the right-hand grip rule for direction.'),
 example=('Force on a moving proton','A proton moves at 2 × 10⁶ m/s perpendicular to a 0.5 T field. Find magnetic-force magnitude.','F = evB = (1.6 × 10⁻¹⁹)(2 × 10⁶)(0.5) = 1.6 × 10⁻¹³ N. Direction follows q(v × B).'),
 questions=[('Why does magnetic force not change a charged particle’s speed?','It is perpendicular to velocity, so its instantaneous work is zero.'),('What is the field outside an ideal long solenoid?','Approximately zero far from its ends.')]),
 dict(id='magnetism-matter',title='Magnetism & Matter',pages='177–207',scope='Bar magnets, magnetic dipoles, Gauss’s law for B and magnetic materials.',
 concept='A bar magnet acts as a magnetic dipole. Magnetic field lines are closed loops: there are no isolated magnetic poles in this treatment. Materials respond differently to an applied field.',
 formulas=[('Magnetic dipole torque','τ = mB sinθ; U = −m·B','m denotes magnetic dipole moment.'),('Gauss’s law for magnetism','∮B·dA = 0','Net magnetic flux through any closed surface is zero.'),('Material response','M = χ_m H; B = μ₀(H + M)','For linear isotropic material: B = μ₀(1+χ_m)H.'),('Earth field components','B_H = B cosδ; B_V = B sinδ','δ is dip angle, with components in the magnetic meridian.')],
 derivation=('Torque on a magnetic dipole','For a small current loop in uniform B, opposite sides experience equal and opposite forces. Their resultant force is zero but they form a couple. The torque is τ = IAB sinθ for one turn, or NIAB sinθ for N turns. Defining m = NIA gives τ = mB sinθ, tending to align m with B.'),
 example=('Dipole torque','A loop has magnetic moment 0.20 A·m² in a 0.50 T field at 30° to B. Find its torque.','τ = mB sin30° = (0.20)(0.50)(0.5) = 0.05 N·m.'),
 questions=[('Why do magnetic field lines have no beginning or end?','No magnetic monopoles are observed in this model; the field has zero net closed-surface flux.'),('Name the three broad magnetic material classes.','Diamagnetic, paramagnetic and ferromagnetic.')]),
 dict(id='electromagnetic-induction',title='Electromagnetic Induction',pages='208–236',scope='Magnetic flux, Faraday and Lenz, motional emf, self/mutual induction.',
 concept='Changing magnetic flux through a circuit induces emf. Lenz’s law specifies the current direction: the induced effect opposes the change in flux, conserving energy.',
 formulas=[('Flux','Φ_B = BA cosθ','Angle θ is between B and the area normal.'),('Faraday–Lenz','ε = −N dΦ_B/dt','Magnitude for a uniform change: |ε| = N|ΔΦ|/Δt.'),('Motional emf','ε = Bℓv','Straight rod ℓ moving perpendicular to uniform B.'),('Self-induction','ε_L = −L dI/dt; U_L = ½LI²','Inductor opposes changes in current.')],
 derivation=('Motional emf of a rod','A conducting rod of length ℓ moves at speed v perpendicular to a uniform field B. Charges in it feel magnetic force qvB. Charge separation builds an electric force qE; at equilibrium qE = qvB, so E = vB. The end-to-end potential difference is ε = Eℓ = Bℓv. The circuit current requires a closed path.'),
 example=('Changing-flux coil','A 100-turn coil has flux per turn changing from 0.020 Wb to 0.005 Wb in 0.10 s. Find average emf magnitude.','|ε| = 100 × |0.005 − 0.020| / 0.10 = 15 V. Direction needs the field orientation and Lenz’s law.'),
 questions=[('Why is there a minus sign in Faraday’s law?','It encodes Lenz’s law: induced emf opposes the flux change.'),('Can an emf be induced without physically moving the loop?','Yes, if the magnetic field or loop orientation/area changes so the flux changes.')]),
 dict(id='alternating-current',title='Alternating Current',pages='237–272',scope='AC rms, reactance, LCR, resonance, power factor and transformer.',
 concept='An alternating source changes sign periodically. Inductors and capacitors affect current through frequency-dependent reactance; in a series LCR circuit the current peaks at resonance.',
 formulas=[('RMS values','V_rms = V₀/√2; I_rms = I₀/√2','Valid for sinusoidal AC.'),('Reactances','X_L = ωL; X_C = 1/(ωC); ω = 2πf','Pure L: current lags voltage; pure C: current leads.'),('Series LCR','Z = √[R²+(X_L−X_C)²]; I_rms = V_rms/Z','tanφ = (X_L−X_C)/R.'),('Resonance','ω₀ = 1/√(LC); f₀ = 1/(2π√LC)','At resonance: X_L=X_C, Z=R.'),('Power and transformer','P_avg = V_rms I_rms cosφ; V_s/V_p = N_s/N_p','Ideal transformer only; real losses exist.')],
 derivation=('Series LCR impedance','Take current as reference. Resistor voltage is in phase with current, inductor voltage leads it by 90°, capacitor voltage lags by 90°. The reactive voltages oppose: V_rms² = (I_rmsR)² + [I_rms(X_L−X_C)]². Thus Z = V_rms/I_rms = √[R²+(X_L−X_C)²]. At resonance X_L=X_C, so Z=R.'),
 example=('Impedance and current','For a series circuit with R=30 Ω, X_L=50 Ω, X_C=10 Ω and V_rms=100 V, find Z and I_rms.','Z = √(30²+40²) = 50 Ω. I_rms = 100/50 = 2 A.'),
 questions=[('What happens to series LCR impedance at resonance?','It becomes minimum and equals R; current is maximum for fixed rms voltage.'),('Can a transformer work on steady DC?','No steady induced secondary emf occurs without changing flux.')]),
 dict(id='electromagnetic-waves',title='Electromagnetic Waves',pages='273–291',scope='Displacement current, EM-wave properties and spectrum applications.',
 concept='A time-varying electric field contributes to a magnetic field (displacement current). In vacuum an electromagnetic wave has mutually perpendicular electric and magnetic fields, both transverse to propagation.',
 formulas=[('Vacuum speed','c = 1/√(μ₀ε₀) ≈ 3 × 10⁸ m/s','In vacuum, c = fλ.'),('Field amplitudes','E₀/B₀ = c','Fields are in phase for a plane wave in vacuum.'),('Displacement current','I_d = ε₀ dΦ_E/dt','Important between charging capacitor plates.'),('Intensity','I_avg = ½ ε₀c E₀²','For a sinusoidal plane wave in vacuum.')],
 derivation=('Why a charging capacitor needs displacement current','Apply Ampère’s law to a loop around a charging wire. A spanning surface cutting the wire encloses conduction current I, while a surface bulging between capacitor plates has no conduction current. Maxwell added I_d = ε₀ dΦ_E/dt. Between ideal plates Φ_E = EA = Q/ε₀, so I_d = dQ/dt = I; both surfaces give the same magnetic field.'),
 example=('Wavelength','An EM wave in vacuum has frequency 100 MHz. Find wavelength.','λ = c/f = (3 × 10⁸)/(100 × 10⁶) = 3 m.'),
 questions=[('What are the directions of E, B and propagation in a plane EM wave?','They are mutually perpendicular; the propagation direction follows E × B.'),('Order radio waves, visible light and X-rays by increasing frequency.','Radio waves → visible light → X-rays.')])]
assert len(chapters)==8
katex_formulas=json.loads(subprocess.check_output(['node','render-physics-formulas.js'],cwd=R,text=True,encoding='utf-8'))
assert set(katex_formulas)=={c['id'] for c in chapters}
assert all(len(katex_formulas[c['id']])==len(c['formulas']) for c in chapters)

css='''@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Libre+Baskerville:wght@400;700&display=swap');
:root{--bg:#f7f3ed;--ink:#172436;--muted:#565d6b;--border:#dfd6cc;--accent:#9c431c;--tint:#f8eee4}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.57 'DM Sans',Arial,sans-serif}a{color:var(--accent)}.wrap{width:min(780px,calc(100% - 32px));margin:auto}.bar{background:#fff;border-bottom:1px solid var(--border)}.bar .wrap{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:58px}.brand{font-weight:700;text-decoration:none;color:var(--ink);white-space:nowrap}.nav{display:flex;gap:5px;overflow-x:auto;white-space:nowrap}.nav a{font-size:13px;text-decoration:none;padding:8px;border-radius:7px}.nav a[aria-current],.nav a:hover{background:var(--tint)}.hero{padding:27px 0 10px}.eyebrow{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:700;color:var(--accent)}h1{font:700 clamp(27px,5vw,38px)/1.2 'Libre Baskerville',Georgia,serif;letter-spacing:-.025em;margin:8px 0}h2{font:700 21px/1.35 'Libre Baskerville',Georgia,serif;margin:0 0 10px}h3{font-size:16px;margin:17px 0 7px}p{margin:8px 0;color:var(--muted)}main{padding-bottom:42px}.card{background:#fff;border:1px solid var(--border);border-radius:12px;padding:19px 21px;margin:13px 0}.alert{background:#fff8e7;border-color:#e5d2a7}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.cards a{display:block;background:#fff;border:1px solid var(--border);border-radius:11px;padding:15px 16px;text-decoration:none;min-height:105px;color:var(--ink)}.cards a:hover{border-color:var(--accent)}.cards small,.muted{font-size:12px;color:var(--muted)}.cards strong{display:block;margin-top:4px;line-height:1.3}.btn{display:inline-block;background:var(--accent);color:#fff;padding:10px 15px;border-radius:8px;text-decoration:none;font-weight:700;min-height:44px}.btn.alt{background:#fff;color:var(--accent);border:1px solid var(--border)}.actions{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.tabs{display:flex;gap:7px;overflow-x:auto;margin:14px 0}.tabs a{background:#fff;border:1px solid var(--border);border-radius:8px;white-space:nowrap;padding:9px 12px;text-decoration:none;font-size:13px}.formula{border-top:1px solid var(--border);padding:11px 0}.formula:first-of-type{border-top:0}.equation{display:block;font:600 17px/1.45 'DM Sans',Arial,sans-serif;color:var(--ink);overflow-x:auto;padding:5px 0;white-space:nowrap}.formula small{color:var(--muted)}.steps{background:var(--tint);padding:11px 15px;border-radius:7px;white-space:pre-line;color:var(--ink)}details{border-top:1px solid var(--border);padding:10px 0}summary{cursor:pointer;font-weight:600;color:var(--accent);min-height:35px}details p{padding:7px 10px;background:var(--tint);border-radius:7px}.foot{border-top:1px solid var(--border);padding:20px 0;font-size:12px}.tag{display:inline-block;background:var(--tint);border-radius:20px;padding:4px 9px;font-size:12px;color:var(--accent);font-weight:700}.quiz{border-top:1px solid var(--border);padding:11px 0}.quiz strong{display:block}.source{font-size:12px;color:var(--muted)}:focus-visible{outline:3px solid #b87237;outline-offset:2px}@media(max-width:600px){.cards{grid-template-columns:1fr}.card{padding:15px}.nav a{font-size:12px;padding:7px}.equation{font-size:15px}}@media print{.bar,.actions,.tabs{display:none}body{background:#fff}.card{break-inside:avoid}}'''
(R/'physics-guide.css').write_text(css+'\n/* Accessible, pre-rendered KaTeX formulas; no client-side JavaScript required. */\n.equation{display:flex;flex-wrap:wrap;align-items:center;gap:8px 25px;overflow-x:visible;white-space:normal;font-size:18px;line-height:1.7;padding:9px 0}\n.math-line{max-width:100%;overflow-x:auto;overflow-y:hidden;padding:3px 0}\n.math-line .katex{font-size:1.1em;white-space:nowrap}\n@media(max-width:600px){.equation{font-size:16px;gap:8px 16px}.math-line .katex{font-size:1.06em}}\n',encoding='utf8')
nav=[('physics.html','Home'),('physics-formulas.html','Formulas'),('physics-derivations.html','Derivations'),('physics-practice.html','Practice'),('physics-pyq.html','ASSEB papers')]
def page(title,sub,body,active=''):
    navhtml=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==u else '')+f'>{E(n)}</a>' for u,n in nav)
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f3ed"><title>'+E(title)+' · Physics Focus</title><link rel="stylesheet" href="katex-fonts.css"><link rel="stylesheet" href="physics-guide.css"></head><body><header class="bar"><div class="wrap"><a class="brand" href="physics.html">Focus · Physics</a><nav class="nav" aria-label="Physics navigation">'+navhtml+'</nav></div></header><div class="wrap"><div class="hero"><span class="eyebrow">HS 2nd year · Physics</span><h1>'+E(title)+'</h1><p>'+E(sub)+'</p></div><main>'+body+'</main></div><footer class="foot"><div class="wrap">Made by Debashish · Based on NCERT Physics Part I. Practice is not a prediction. <a href="index.html">Main study plan</a></div></footer></body></html>'
def card(t,body,cl=''):return '<section class="card '+cl+'"><h2>'+E(t)+'</h2>'+body+'</section>'
for name in ['index.html','subjects.html']:
    old=(R/name).read_text(encoding='utf8')
    new=old.replace('6 chapters · 50 marks','8 chapters · 50-mark college paper').replace('Electrostatics through electromagnetic induction.','Electrostatics through electromagnetic waves · formulas, derivations and examples.').replace('6 chapters · direct chapter lessons','8 chapters · formulas, derivations and practice')
    if name=='index.html':
        new=new.replace('Seven papers. Clear sequence.','Physics is next · 50 marks.').replace('The preparation phase prioritises PCM. English, General Studies, Alternative English and CSCA each have a dedicated day.','Open the new Physics guide for eight chapter sections, formulas, derivations, worked examples and sourced ASSEB board practice.').replace('One plan.<br>Nothing extra.','Physics tomorrow.<br>Study by section.').replace('Start 10 September. Study six focused hours a day. Finish every required chapter before the first paper.','Your 50-mark college Physics paper is next. Open eight clear chapter guides, formulas, derivations, solved problems and ASSEB past-paper practice.').replace('View today’s plan','Open Physics revision').replace('href="plan.html">Open Physics revision','href="physics.html">Open Physics revision').replace('Start with Solutions.','Start with Physics.').replace('Chemistry for four hours. Relations and Functions for two. Learn, solve, recall.','Review formulas, write derivations from memory and solve a mixed set.').replace('Open Chemistry','Open Physics').replace('href="chemistry.html">Open Physics','href="physics.html">Open Physics').replace('<b>10</b><span>Sep</span>','<b>30</b><span>Sep</span>').replace('<b>15</b><span>full days before English','<b>1</b><span>day until Physics')
    if new!=old:(R/name).write_text(new,encoding='utf8')
def formula_html(c):
    rendered=katex_formulas[c['id']]
    assert len(rendered)==len(c['formulas']),c['id']
    return ''.join('<div class="formula"><strong>'+E(n)+'</strong><div class="equation" role="math">'+''.join('<div class="math-line">'+fragment+'</div>' for fragment in rendered[i])+'</div><small>'+E(note)+'</small></div>' for i,(n,f,note) in enumerate(c['formulas']))
def question_html(c):return ''.join('<div class="quiz"><strong>'+E(q)+'</strong><details><summary>Show answer</summary><p>'+E(a)+'</p></details></div>' for q,a in c['questions'])
def book_note(c):return '<p class="source">Source: NCERT Physics Part I, PDF pages '+E(c['pages'])+'. These are teaching notes, not quotations from the book.</p>'
links=''.join('<a href="physics-'+c['id']+'.html"><small>Chapter '+str(i+1)+' · NCERT PDF pp. '+E(c['pages'])+'</small><strong>'+E(c['title'])+'</strong><small>'+E(c['scope'])+'</small></a>' for i,c in enumerate(chapters))
warning='<p><strong>Scope check:</strong> these eight chapters match the earlier Bongaigaon district half-yearly list, not a verified Pandu College chapter notice. Your college paper is <strong>50 marks</strong>; no reliable local question distribution is known. Skip any chapter your teacher explicitly excludes.</p>'
home=card('Tomorrow’s revision', '<p>Read one chapter at a time: <strong>concept → formulas → derivation → solved example → two short questions</strong>. Then attempt NCERT exercises on paper. Finish with real ASSEB board papers for question style; they are not your college’s 50-mark pattern.</p><div class="actions"><a class="btn" href="physics-formulas.html">Start with formulas</a><a class="btn alt" href="physics-pyq.html">See ASSEB past papers</a><a class="btn alt" href="'+book+'" target="_blank" rel="noopener">Open your textbook link</a></div>')+card('Important scope warning',warning,'alert')+'<h2 id="chapters">Eight chapter guides</h2><div class="cards">'+links+'</div>'+card('How to use the last hours','<p>Choose three weak chapters for active practice; do not spend the whole night reading. Reproduce derivations without looking, solve a numerical from each important section and keep a one-page error list. The morning pass should be formulas and your mistakes, not new theory.</p>')
(R/'physics.html').write_text(page('Physics · clear revision','50-mark college paper · eight-chapter working scope · separate formulas, derivations and examples.',home,'physics.html'),encoding='utf8')
for i,c in enumerate(chapters):
    anchor='<div class="tabs"><a href="#concept">Concept</a><a href="#formulas">Formulas</a><a href="#derivation">Derivation</a><a href="#example">Example</a><a href="#questions">Questions</a></div>'
    body='<p class="source">NCERT Physics Part I · chapter '+str(i+1)+' · PDF pages '+E(c['pages'])+'</p>'+anchor
    body+='<section class="card" id="concept"><h2>Understand the idea</h2><p>'+E(c['concept'])+'</p></section>'
    body+='<section class="card" id="formulas"><h2>Formulas · know when to use them</h2>'+formula_html(c)+'</section>'
    body+='<section class="card" id="derivation"><h2>Derivation · '+E(c['derivation'][0])+'</h2><p class="steps">'+E(c['derivation'][1])+'</p></section>'
    body+='<section class="card" id="example"><h2>Worked example · '+E(c['example'][0])+'</h2><p>'+E(c['example'][1])+'</p><p class="steps">'+E(c['example'][2])+'</p></section>'
    body+='<section class="card" id="questions"><h2>Check yourself</h2>'+question_html(c)+book_note(c)+'</section>'
    nxt=chapters[i+1] if i<7 else None
    body+='<div class="actions"><a class="btn alt" href="physics.html#chapters">← All chapters</a>'+(f'<a class="btn" href="physics-{nxt["id"]}.html">Next chapter →</a>' if nxt else '<a class="btn" href="physics-practice.html">Mixed practice →</a>')+'</div>'
    (R/('physics-'+c['id']+'.html')).write_text(page(c['title'],c['scope'],body),encoding='utf8')
formula_body='<p class="tag">All eight chapters · printable</p>'+''.join(card(str(i+1)+'. '+c['title'],formula_html(c)+book_note(c)) for i,c in enumerate(chapters))
(R/'physics-formulas.html').write_text(page('Formula desk','Names, equations and the condition that makes each equation usable.',formula_body,'physics-formulas.html'),encoding='utf8')
deriv_body=card('How to earn derivation marks','<p>Write the diagram or geometry, symmetry/assumptions, defining equation, algebra and boxed final result. Do not memorise an unexplained last line. A full-board PYQ is not a guaranteed half-yearly question.</p>')+''.join(card(str(i+1)+'. '+c['derivation'][0],'<p class="steps">'+E(c['derivation'][1])+'</p><p><a href="physics-'+c['id']+'.html">Open chapter and example →</a></p>'+book_note(c)) for i,c in enumerate(chapters))
(R/'physics-derivations.html').write_text(page('Derivation workshop','Eight compact step-by-step proofs you can rewrite without looking.',deriv_body,'physics-derivations.html'),encoding='utf8')
practice_body=card('Worked examples · one per chapter','<p>Try each problem without opening the solution. Use SI units and check the physical direction when relevant.</p>')+''.join(card(str(i+1)+'. '+c['example'][0]+' · '+c['title'],'<p>'+E(c['example'][1])+'</p><details><summary>Show worked solution</summary><p>'+E(c['example'][2])+'</p></details>'+question_html(c)) for i,c in enumerate(chapters))
(R/'physics-practice.html').write_text(page('Numericals & quick checks','Eight worked examples plus concept questions with hidden answers.',practice_body,'physics-practice.html'),encoding='utf8')
pyq_examples=[
('2025 · 1 mark · p. 4','An electron follows a helical path in a magnetic field. What determines its pitch?','The velocity component parallel to B sets the pitch: pitch = v_parallel T, where T = 2πm/(|q|B).','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','moving-charges-magnetism'),
('2025 · 2 marks · p. 8','A 10 V battery has 3 Ω internal resistance and supplies 0.5 A. Find terminal voltage.','V = ε − Ir = 10 − (0.5)(3) = 8.5 V.','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','current-electricity'),
('2025 · 2 marks · p. 8','State the magnetic force on a moving charge and define one tesla.','F = q(v × B). One tesla gives a 1 N magnetic force on a 1 C charge moving at 1 m/s perpendicular to the field.','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','moving-charges-magnetism'),
('2025 · 2 marks · p. 8','For U = −m·B, identify a magnetic needle’s most stable and unstable orientations.','Stable: m parallel to B (minimum U = −mB). Unstable: m antiparallel to B (maximum U = +mB).','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','magnetism-matter'),
('2025 · 2 marks · p. 9','A 44 mH inductor is connected to a 220 V, 50 Hz AC supply. Find its rms current.','X_L = 2πfL ≈ 13.82 Ω; I_rms = 220/13.82 ≈ 15.9 A (ideal inductor).','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','alternating-current'),
('2025 · 3 marks · p. 12','Derive the capacitance of two large parallel plates of area A, separation d, carrying ±Q.','Neglect edges: E = Q/(ε₀A); V = Ed; C = Q/V = ε₀A/d.','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','potential-capacitance'),
('2025 · 3 marks · p. 13','State Ampère’s circuital law and use it to find B at distance r from an indefinitely long straight current I.','∮B·dl = μ₀I. Circular path gives B(2πr)=μ₀I, hence B=μ₀I/(2πr).','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','moving-charges-magnetism'),
('2025 · 3 marks · p. 14','Give one distinction between an AC generator and a motor; draw a labelled AC generator.','Generator converts mechanical energy to electrical energy; motor does the reverse. Label coil, slip rings, axle and carbon brushes in your diagram.','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','electromagnetic-induction'),
('2025 · 5 marks · p. 21','For series LCR with L=5.0 H, C=80 μF, R=40 Ω on 230 V rms at ω=50 rad/s, find Z and rms drops across R, L, C.','X_L = 250 Ω; X_C = 250 Ω, so resonance: Z=40 Ω and I=5.75 A. Drops: V_R=230 V, V_L=1437.5 V, V_C=1437.5 V; reactive drops cancel as phasors.','https://docs.aglasem.com/view/8ae457da-4c25-11f0-b7b3-0a5e36bc6706','alternating-current')]
pyq_cards=''.join(card(item[0],'<p><span class="tag">'+E(chapters[next(i for i,c in enumerate(chapters) if c['id']==item[4])]['title'])+'</span></p><p>'+E(item[1])+'</p><details><summary>Show suggested answer</summary><p>'+E(item[2])+'</p></details><p class="source">Paraphrased from the scanned English section of the Assam HS 2025 Physics board paper, PDF page '+E(item[0].split('p. ')[1])+'. <a href="'+E(item[3])+'" target="_blank" rel="noopener">Check source paper ↗</a></p>') for item in pyq_examples)
